def transform(grid):
    # Function to find the bounding box coordinates of all cells of a specific color
    def find_box(color):
        min_r, max_r = len(grid), -1
        min_c, max_c = len(grid[0]), -1

        for r in range(len(grid)):
            for c in range(len(grid[0])):
                if grid[r][c] == color:
                    if r < min_r: min_r = r
                    if r > max_r: max_r = r
                    if c < min_c: min_c = c
                    if c > max_c: max_c = c

        return min_r, max_r, min_c, max_c

    # Step 1: Count occurrences of each color to identify the unique marker (count 4)
    counts = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            val = grid[r][c]
            counts[val] = counts.get(val, 0) + 1

    # Step 2: Find the marker color. In ARC tasks for this pattern, the marker often appears
    # exactly 4 times (at the corners of the bounding box). We look for a color with 4 occurrences.
    marker = None
    for color in sorted(counts.keys(), key=lambda x: counts[x]):
        if counts[color] == 4:
            marker = color
            break

    if marker is None:
        # If no unique count 4 marker is found (or logic differs for other tasks), fallback to returning grid
        # or use the background. Here we fallback to returning the grid as is.
        return grid

    # Step 3: Locate the marker's bounding box in the grid
    min_r, max_r, min_c, max_c = find_box(marker)

    # If the marker wasn't found (shouldn't happen if check passed), return grid
    if max_r == -1 or min_c > max_c:
        return grid

    # Step 4: Crop the grid to the bounding box defined by the marker
    return grid[min_r:max_r+1][min_c:max_c+1]
